#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill: first npm publish and trusted publishers for the workspace packages.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

# Never read or write a .env file: this wizard captures no persisted values.
ENV_FILE=/dev/null

OWNER="awalsh128"
REPO_SLUG="awalsh128/vsce-winston-logging"
WORKFLOW="publish.yml"
ENVIRONMENT="release"
PACKAGES=(winston-host winston-vscode winston-github-actions)
NPM_OTP=""

die() { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET" >&2; exit 1; }

# ask_otp reads the current 2FA code into NPM_OTP; blank means approve in the browser.
ask_otp() {
  NPM_OTP=""
  note "Codes are single-use and expire in about 30 seconds: type it just before pressing Enter."
  ask_secret NPM_OTP "Authenticator code (blank to approve in the browser instead):" || NPM_OTP=""
}

# publish_bootstrap PKG publishes a throwaway 0.0.1 under the "bootstrap" tag, so the package
# exists on npm and can be given a trusted publisher. The committed package.json is always restored.
publish_bootstrap() {
  local pkg="$1" name="@awalsh128/$1" ok
  if npm view "$name" version >/dev/null 2>&1; then
    say "$name is already on npm, so there is nothing to publish."
    return 0
  fi
  say "Publishing $name@0.0.1 with the 'bootstrap' tag (not 'latest'), without provenance."
  while true; do
    ask_otp
    local args=(--access public --tag bootstrap --provenance=false)
    [[ -n "$NPM_OTP" ]] && args+=("--otp=$NPM_OTP")
    ok=0
    if (cd "$REPO/packages/$pkg" && npm pkg set version=0.0.1 >/dev/null && npm publish "${args[@]}"); then ok=1; fi
    git -C "$REPO" checkout -- "packages/$pkg/package.json"
    (( ok )) && break
    warn "The publish failed."
    if ! confirm "Try again with a fresh code?"; then
      SKIPPED+=("publish $name (see scripts/npm-bootstrap.sh stage for $pkg)")
      return 0
    fi
  done
  say "On npm now:"
  # The registry can lag a moment after a publish, so a miss here is not an error.
  npm view "$name" dist-tags --json 2>/dev/null | sed 's/^/    /' || true
}

# trust_package PKG adds a trusted publisher for this repository's publish workflow.
trust_package() {
  local pkg="$1" name="@awalsh128/$1"
  # --allow-publish: the whole point is letting this workflow publish. Not verified against the
  # CLI's default, so the dry run below shows what npm will do.
  local cmd=(npm trust github "$name" --file "$WORKFLOW" --repo "$REPO_SLUG" --env "$ENVIRONMENT" --allow-publish --yes)
  say "Dry run (changes nothing):"
  "${cmd[@]}" --dry-run 2>&1 | grep -v '^npm notice' | sed 's/^/    /' || true
  confirm "Add the trusted publisher for $name?" || { SKIPPED+=("trusted publisher for $name"); return 0; }
  while true; do
    ask_otp
    local args=("${cmd[@]}")
    [[ -n "$NPM_OTP" ]] && args+=("--otp=$NPM_OTP")
    if "${args[@]}"; then return 0; fi
    warn "npm trust failed (it also fails if one is already set; check with the last stage)."
    if confirm "Try again with a fresh code?"; then continue; fi
    say "Or set it in the browser instead:"
    open_url "https://www.npmjs.com/package/$name/access"
    step "Trusted publisher → GitHub Actions: owner $OWNER, repository ${REPO_SLUG#*/},"
    step "workflow filename $WORKFLOW, environment $ENVIRONMENT. Save."
    pause "Press Enter once it is saved (or to skip)."
    return 0
  done
}

banner "npm: first publish and trusted publishers"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check this checkout"
REPO=$(git rev-parse --show-toplevel 2>/dev/null) || die "Run this from inside the vsce-winston-logging checkout."
cd "$REPO"
[[ "$(git remote get-url origin)" == *"$REPO_SLUG"* ]] || die "origin is not $REPO_SLUG."
git diff --quiet && git diff --cached --quiet || die "Tracked files have uncommitted changes. Commit or stash them first."
git fetch -q origin staging
if [[ "$(git rev-parse HEAD)" != "$(git rev-parse origin/staging)" ]]; then
  warn "HEAD is $(git rev-parse --short HEAD), not origin/staging ($(git rev-parse --short origin/staging))."
  confirm "Publish from this commit anyway?" || die "Check out and pull staging, then re-run."
fi
NPM_VERSION=$(npm --version)
[[ "$(printf '%s\n11.5.1\n' "$NPM_VERSION" | sort -V | head -n1)" == "11.5.1" ]] \
  || die "npm $NPM_VERSION is too old for trusted publishing (needs 11.5.1 or newer)."
say "npm $NPM_VERSION, clean tree, on $(git rev-parse --short HEAD). Installing and building..."
npm ci --silent
npm run --silent build
say "Build OK."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Log in to npm"
if [[ "$(npm whoami 2>/dev/null || true)" != "$OWNER" ]]; then
  say "Not logged in as $OWNER. npm will print a login URL; approve it in the browser."
  npm login
fi
WHO=$(npm whoami 2>/dev/null || true)
[[ "$WHO" == "$OWNER" ]] || die "Logged in as '${WHO:-nobody}', not '$OWNER'. The @$OWNER scope belongs to that user."
say "Logged in as $WHO. The @$OWNER scope is yours."

# ── 3-5 ───────────────────────────────────────────────────────────────────
for pkg in "${PACKAGES[@]}"; do
  stage "Publish a throwaway $pkg"
  publish_bootstrap "$pkg"
done

# ── 6-8 ───────────────────────────────────────────────────────────────────
for pkg in "${PACKAGES[@]}"; do
  stage "Trusted publisher for $pkg"
  say "Lets the $WORKFLOW workflow (environment '$ENVIRONMENT') publish @$OWNER/$pkg without a token."
  trust_package "$pkg"
done

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Verify"
for pkg in "${PACKAGES[@]}"; do
  name="@awalsh128/$pkg"
  tags=$(npm view "$name" dist-tags --json 2>/dev/null || echo "{}")
  say "$name: $(printf '%s' "$tags" | tr -d '\n ')"
  [[ "$tags" == *'"latest"'* ]] && warn "$name has a 'latest' tag; the first automated 1.0.0 will replace it."
done
say ""
say "Trusted publishers (each listing needs a fresh code, or browser approval):"
for pkg in "${PACKAGES[@]}" vsce-winston-logging; do
  name="$pkg"; [[ "$pkg" != vsce-winston-logging ]] && name="@awalsh128/$pkg"
  confirm "List the trusted publisher of $name?" || continue
  ask_otp
  args=(npm trust list "$name")
  [[ -n "$NPM_OTP" ]] && args+=("--otp=$NPM_OTP")
  "${args[@]}" 2>&1 | grep -v '^npm notice' | sed 's/^/    /' || warn "couldn't list $name"
done
say ""
note "Each entry should show $REPO_SLUG, workflow $WORKFLOW and environment $ENVIRONMENT."
note "Next, back in Claude: dry-run publish.yml, then run Promote staging to main."

finish
}

run_wizard "$@"; exit
